  /* une plaque d'armure, 12 × 12 : tombe au sol à la phase 2 ; ':sol' la montre éteinte, en sang et ardoise */
  function genCyclopePlaque(variant) {
    var s = spr(12, 12), x, y, sol = variant === 'sol';
    for (y = 0; y < 12; y++) for (x = 0; x < 12; x++) {
