          O.spark(q.x, q.y, O.ROSE, 4);
        }
        e._st = 'recup'; e._stT = CFG.larveRecup; e._cd = rr(CFG.larveCd[0], CFG.larveCd[1]);
      }
    } else if (e._st === 'recup') {
