  }

  /* ---- RIVAL : l'autre serpent (traînée mortelle, coupe-route) ---- */
  function updRival(e, dt, P) {
    var c = conf('rival'), v = (c.vitesse || 0.9) * Math.max(50, vitesseTete()) * allure(e);
    var A = O.A, mar = c.evitementMurs || 24;
