    if (id === 'canon') {
      if (i === 1) { l1 = '2 BOUCHES ALTERNÉES'; l2 = f1(pr.cadence) + ' → ' + f1(p.cadence) + ' TIRS/S'; }
      else if (i === 2) { l1 = '2 LANCES PERÇANTES'; l2 = 'DÉGÂTS ' + pr.degats + ' → ' + p.degats; }
      else { l1 = 'RAYON CONTINU'; l2 = p.degats + ' DÉG · ' + p.tics + '/S'; }
    } else if (id === 'tourelles') {
